  const text=lc(`${get(row,['Niche'])} ${get(row,['Business Type'])} ${get(row,['Market'])}`);
  if(/\b(furniture|manufacturer|manufacturing|factory|workshop|joinery|cabinetry|upholstery|wholesale|private label|oem|procurement|rfq)\b/i.test(text))return 'FURNITURE';
  if(/\b(architect|architecture|interior design|interior studio|design studio|landscape architecture)\b/i.test(text))return 'ARCHITECTURE';
  if(/\b(hotel|resort|villa|lodge|inn|guest ?house|retreat|accommodation|farm stay|farm-stay|hospitality|overnight stays?|weddings?|wedding venue)\b/i.test(text))return 'HOSPITALITY';
  if(/\b(catering|bakery|patisserie|restaurant|cafe|coffee|winery|vineyard|distillery|tasting|private dining)\b/i.test(text))return 'FNB';
  return 'HOSPITALITY';
}
function planFor(row){
  const company=norm(get(row,['Company']));
  const email=norm(get(row,['Official Email']));
  const notes=norm(get(row,['Notes']));
  const fact=oneLine(get(row,['Trigger']))||oneLine(marker(notes,'CORE ASSET'))||oneLine(get(row,['Purchasing Power Signals']))||assetPhrase(row);
  const gap=oneLine(get(row,['Commercial Gap']))||oneLine(marker(notes,'COMMERCIAL IMPLICATION'));
  if(!company||!validEmail(email)||!fact||!gap)return null;
  const cat=category(row);
  const brand=shortBrand(company);
  const asset=assetPhrase(row);
  const gapText=lc(gap);
  const event=/\b(event|wedding|occasion|celebration|banquet|conference|retreat)\b/i.test(`${gap} ${asset}`);
  const useId=lc(get(row,['Country']))==='indonesia';
  let subject='',gapLine='',consequence='',capability='',mechanism='',outcome='';
  if(cat==='FURNITURE'){
    subject=`${brand} RFQ details`;
    gapLine=useId?'Buyer proyek belum bisa cepat menemukan spesifikasi, ketentuan pesanan, atau input RFQ yang dibutuhkan.':"Project buyers can't quickly find the specifications, order details, or RFQ inputs they need.";
    consequence=useId?'Ini bisa menghasilkan inquiry yang terlalu umum atau menambah pekerjaan procurement.':'That can create vague enquiries or extra procurement work before they reach out.';
    capability=useId?'produsen proyek mengubah kemampuan produksi menjadi RFQ yang lebih terarah':'project manufacturers turn production capability into qualified RFQs';
    mechanism=useId?'menempatkan spesifikasi, bukti produksi, dan detail RFQ dalam satu langkah keputusan':'place specifications, production proof, and RFQ details in one decision step';
    outcome=useId?'RFQ proyek yang lebih terarah':'qualified project RFQs';
  }else if(cat==='ARCHITECTURE'){
    subject=`${brand} project proof context`;
    gapLine=useId?'Halaman proyek belum memudahkan buyer menilai peran, scope, atau batasan proyek.':"The project pages don't make your role, scope, or constraints easy to assess.";
    consequence=useId?'Ini bisa membuat buyer tertarik tetapi tetap ragu apakah studio tersebut cocok.':'That can leave a buyer interested but unsure whether the studio fits.';
    capability=useId?'studio arsitektur dan interior mengubah bukti proyek menjadi inquiry yang lebih terarah':'architecture and interior studios turn project proof into qualified enquiries';
    mechanism=useId?'menempatkan peran, scope, dan hasil di samping proyek yang relevan':'place role, scope, and outcome beside the relevant work';
    outcome=useId?'inquiry proyek yang lebih terarah':'qualified project enquiries';
  }else if(cat==='FNB'){
    subject=event?`${brand} event enquiry path`:`${brand} reservation path`;
    gapLine=useId?'Buyer masih harus menentukan sendiri jenis acara, format layanan, dan jalur permintaan yang tepat.':'Guests still have to work out the right occasion, format, and reservation or enquiry path.';
    consequence=useId?'Ini menambah usaha sebelum reservasi atau permintaan acara yang serius dikirim.':'That adds effort before a serious reservation or event request is made.';
    capability=useId?'bisnis F&B premium mengubah minat acara menjadi inquiry yang lebih berguna':'premium food businesses turn occasion interest into useful enquiries';
    mechanism=useId?'mencocokkan setiap acara dengan penawaran dan detail permintaan yang tepat':'connect each occasion to the right offer and request details';
    outcome=useId?'inquiry reservasi atau acara yang lebih siap':'more useful reservation and event enquiries';
  }else{
    subject=event?`${brand} event enquiry path`:`${brand} booking choice`;
    if(event){
      gapLine=useId?'Buyer acara masih harus menyusun sendiri penawaran dan jalur inquiry yang paling sesuai.':'Event buyers still have to piece together the right offer and enquiry route.';
      consequence=useId?'Ini bisa menunda inquiry serius atau membuat mereka kembali membandingkan.':'That may delay a serious enquiry or keep them comparing.';
      mechanism=useId?'menghubungkan setiap acara dengan bukti dan langkah inquiry yang tepat':'connect each occasion to the right proof and enquiry step';
      outcome=useId?'inquiry acara yang lebih terarah':'qualified event enquiries';
    }else{
      gapLine=useId?'Calon tamu masih harus menentukan sendiri pilihan menginap dan langkah inquiry yang tepat.':'Guests still have to work out the right stay choice and enquiry path.';
      consequence=useId?'Ini bisa membuat mereka terus membandingkan sebelum booking atau menghubungi langsung.':'That may keep them comparing before they book or enquire directly.';
      mechanism=useId?'mencocokkan setiap pilihan menginap dengan bukti dan langkah inquiry yang tepat':'match each stay choice to the right proof and enquiry step';
      outcome=useId?'lebih banyak niat direct booking dan inquiry yang terarah':'more direct booking intent and qualified enquiries';
    }
    capability=useId?'bisnis hospitality independen meningkatkan keputusan direct booking dan kualitas inquiry':'independent hospitality businesses improve direct booking and qualified enquiries';
  }
  const subjectWords=words(subject);
  if(subjectWords.length<3)subject=`${brand} direct enquiry path`;
  if(words(subject).length>7)subject=words(subject).slice(0,7).join(' ');
  return {company,email,cat,brand,asset,fact,gap,subject,gapLine,consequence,capability,mechanism,outcome,useId};
}
function buildBody(row,plan){
  const dm=firstName(get(row,['Decision Maker','Owner or Decision Maker','Owner / Decision Maker']));
  if(plan.useId){
    const hello=dm?`Halo ${dm}`:`Halo tim ${plan.company}`;
    return [
      `${hello} — situs ${plan.company} menampilkan ${plan.asset}. ${plan.gapLine} ${plan.consequence}`,
      '',
      `Saya membantu ${plan.capability}. Saya memetakan satu perubahan praktis untuk ${plan.company} yang akan ${plan.mechanism}, agar menghasilkan ${plan.outcome}.`,
      '',
      `Perlu saya kirim?`,
      '',
      'Salam,',
      'Evan'
    ].join('\n');
  }
  const hello=dm?`Hi ${dm}`:`Hi ${plan.company} team`;
  return [
    `${hello} — your site shows ${plan.asset}. ${plan.gapLine} ${plan.consequence}`,
    '',
    `I help ${plan.capability}. I mapped one practical change for ${plan.company} that would ${plan.mechanism}, supporting ${plan.outcome}.`,
    '',
    'Worth sending?',
    '',
    'Best,',
    'Evan'
  ].join('\n');
}
function replaceCopy(notes,plan,body){
  const raw=String(notes||'');
  const up=raw.toUpperCase();
  const sIdx=up.indexOf('SUBJECT:');
  const bIdx=sIdx>=0?up.indexOf('BODY:',sIdx):-1;
  let suffixIdx=-1;
  if(bIdx>=0){
    for(const token of ['PRICE=PASS','HARD-SELL=PASS','/HUMAN=PASS']){
      const i=up.indexOf(token,bIdx);
      if(i>=0&&(suffixIdx<0||i<suffixIdx))suffixIdx=i;
    }
  }
  const prefix=clean(sIdx>=0?raw.slice(0,sIdx):raw).replace(/[;\s]+$/,'');
  const suffix=clean(suffixIdx>=0?raw.slice(suffixIdx):'PRICE=PASS; HARD-SELL=PASS; /HUMAN=PASS; PRIOR-CONTACT=PASS; SUPPRESSION=PASS').replace(/^[;\s]+/,'');
  const markers=[
    `OBSERVABLE_FACT=${oneLine(plan.fact)}`,
    `COMMERCIAL_GAP=${oneLine(plan.gap)}`,
    `PLAUSIBLE_CONSEQUENCE=${oneLine(plan.consequence)}`,
    `BUYER_OUTCOME=${oneLine(plan.outcome)}`,
    'COPY_VERSION=VAREVANT-QUEUE-REWRITE-V2',
    'COPY_QUALITY=PASS'
  ].join('; ');
  return `${prefix}${prefix?'; ':''}${markers}; SUBJECT: ${oneLine(plan.subject)}; BODY: ${body}; ${suffix}`;
}
const output=[];
for(const row of rows){
  const status=norm(get(row,['Current Status']));
  if(!STATUS_OK.has(status)||existingCopyPass(row)){
    output.push({json:row});
    continue;
  }
  const plan=planFor(row);
  if(!plan){
    output.push({json:{...row,_copyRefreshFailed:true,_copyRefreshReason:'INSUFFICIENT_EXISTING_EVIDENCE'}});
    continue;
  }
  const body=buildBody(row,plan);
  const rewritten={...row,Notes:replaceCopy(get(row,['Notes']),plan,body),_copyRefreshed:true,_copyVersion:'VAREVANT-QUEUE-REWRITE-V2'};
  if(!existingCopyPass(rewritten)){
    output.push({json:{...row,_copyRefreshFailed:true,_copyRefreshReason:'GENERATED_COPY_FAILED_GATE'}});
    continue;
  }
  output.push({json:rewritten});
}
return output;
